import{z as A,x as d,o,c as B,q as i,j as E,D as t,d as e,s as n,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"激活稀疏与 ReLU²","description":"","frontmatter":{"title":"激活稀疏与 ReLU²","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-sparsity.md","filePath":"llm/activation-sparsity.md","lastUpdated":1791413859000}'),p={name:"llm/activation-sparsity.md"};function L(m,a,h,U,u,c){const r=d("Mermaid");return o(),B("div",null,[a[2]||(a[2]=i('<h1 id="激活稀疏与-relu2" tabindex="-1">激活稀疏与 ReLU² <a class="header-anchor" href="#激活稀疏与-relu2" aria-label="Permalink to &quot;激活稀疏与 ReLU²&quot;">​</a></h1><div class="epigraph"><p>SwiGLU 几乎每个通道都亮；换成 ReLU 一类半波，FFN 的中间激活可以大部分是零——跳过的是乘加，掩码随 token 变。</p><footer>—— Mirzadeh et al., ReLU Strikes Back, ICLR 2024；对照 GLU 激活在 LLaMA 族的默认</footer></div><p><a href="/llm/sheared-llama">上一课</a> 静态地改架构宽度。本课形状不变：给定 \\(x\\)，FFN 中间哪些通道为 0，就可以跳过对应列。缺口是 <strong>激活稀疏</strong> 与权重稀疏正交——Wanda 的掩码跨样本固定，这里每步不同。后课 Deja Vu 用小网络预测这张动态掩码；本课先问激活函数把零率放到哪。<span class="marginnote">「与权重稀疏正交」就是&quot;两码事、互不替代&quot;：权重稀疏像把流水线上的某些工位永久拆掉，对所有订单都生效；激活稀疏像每个订单只动用部分工位，换一个订单用的工位就不同。剪枝看的是权重张量，本课看的是每一次输入点亮了哪些通道。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLaMA 一类用 SwiGLU / SiLU，中间激活很少真零，权重再稀，通道仍要算。ReLU（或 ReLU²，即平方 ReLU）把负半轴打成零，统计上可以出现很高的通道稀疏度。Mirzadeh 等人说明：在可比训练预算下，ReLU 族 LLM 能把这张稀疏变成推理跳过，而不必先做权重剪枝。问题是训练时就要用这种激活；对已经训好的 SwiGLU 基座，不能靠「推理时改 ReLU」白嫖，分布全错。</p><p>稀疏度随层、随 token 变。平均 90% 零不代表每步都能跳 90%：热 token 会点亮更多通道，核必须按最坏或按阈值门控。没有门控核，零仍占 FLOPs。<span class="marginnote">数字实例：设中间层有 11008 个通道，90% 为零意味着约 9907 个乘加可以不碰；可一旦来了个&quot;热&quot; token 把零率拉到 50%，收益立刻腰斩。更麻烦的是 GPU 默认不会因为结果是零就跳过计算——没有专门利用稀疏的核，这些零照样占用矩阵乘的全部时间。</span></p><p><span class="marginnote">ReLU²\\((x)=(\\mathrm{ReLU}(x))^2\\) 在部分工作里比 ReLU 更接近 GELU 的平滑正半轴，同时保留精确零。它不是二阶导数魔法，只是形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练或继续预训练换成 ReLU / ReLU² FFN（门控线性层要改结构，不是只改函数名）。推理：对中间激活做阈值或直接利用精确零，跳过 \\(W_\\mathrm{down}\\) 的对应行（以及 \\(W_\\mathrm{up}\\) 的列，若预判）。与 MoE 不同：没有专家表，跳过的是稠密 FFN 的通道子集，通信模式仍是张量并行，不是 All-to-All。</p><p>对冻结的 SwiGLU 模型，一条弱路径是蒸馏到 ReLU 学生，或只在部分层替换再愈合。不要写成「QLoRA 式即插即用」。</p>',10)),(o(),E(s,null,{default:t(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%22%5D%20--%3E%20UP%5B%22%E4%B8%8A%E6%8A%95%E5%BD%B1%22%5D%0A%20%20UP%20--%3E%20ACT%5B%22ReLU%20%2F%20ReLU2%22%5D%0A%20%20ACT%20--%3E%20Z%5B%22%E7%B2%BE%E7%A1%AE%E9%9B%B6%E9%80%9A%E9%81%93%22%5D%0A%20%20Z%20--%3E%20SKIP%5B%22%E8%B7%B3%E8%BF%87%20down%20%E7%9A%84%E5%AF%B9%E5%BA%94%E8%A1%8C%22%5D%0A%20%20SKIP%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("权重稀疏删的是对所有 \\(x\\) 都为零的连接；激活稀疏删的是"),l("strong",null,"这个"),e(" \\(x\\) 上碰巧为零的乘加。表达力在权重里仍满，只是每次前向用子集。这更接近 MoE 的「条件计算」，但路由是激活函数本身，没有可学习门，也没有负载均衡项。代价是训练动态与 GLU 不同：负半轴没有梯度，死通道风险回到早期 ReLU 网的老问题，初始化与学习率要重调。")],-1)),(o(),E(s,null,{default:t(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%83%E9%87%8D%E7%A8%80%E7%96%8F%22%5D%20--%3E%20WP%5B%22%E6%8E%A9%E7%A0%81%E5%9B%BA%E5%AE%9A%EF%BC%8C%E6%89%80%E6%9C%89%E8%BE%93%E5%85%A5%E5%85%B1%E4%BA%AB%22%5D%0A%20%20W%20--%3E%20WC%5B%22%E5%89%AA%E5%AE%8C%20W%20%E7%9C%9F%E7%9A%84%E5%B0%91%E4%B8%80%E5%9D%97%22%5D%0A%20%20A%5B%22%E6%BF%80%E6%B4%BB%E7%A8%80%E7%96%8F%22%5D%20--%3E%20AP%5B%22%E6%8E%A9%E7%A0%81%E9%80%90%20token%20%E5%8F%98%22%5D%0A%20%20A%20--%3E%20AC%5B%22W%20%E6%BB%A1%E9%98%B5%EF%BC%8C%E6%9C%AC%E6%AC%A1%E5%8F%AA%E7%94%A8%E5%AD%90%E9%9B%86%22%5D%0A%20%20WP%20--%3E%20BOTH%5B%22%E4%B8%A4%E8%80%85%E6%AD%A3%E4%BA%A4%EF%BC%8C%E5%8F%AF%E4%BB%A5%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20AP%20--%3E%20BOTH%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>与 <a href="/llm/lora">LoRA</a> 叠：适配器若加在 FFN 上，会改变哪些通道被点亮，稀疏统计要在合并后重测。服务端按未合并 LoRA 测的零率不能当合并后的数。<span class="marginnote">初学者容易以为&quot;换了 ReLU 就自动变快&quot;。实际上零不会自己产生加速：需要门控核把零通道从矩阵乘里显式挑出去，加速比才追得上零率；门控本身还有判断开销，所以论文里的零率是上限，不是承诺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把论文平均稀疏度写成稳定加速比。不要在 decode 的 tiny batch 上预期与 prefill 相同的跳过收益。下一课 Deja Vu：连 ReLU 都不必，用预测器估计「哪些 MLP 神经元、哪些头」对当前上下文有用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活稀疏是逐 token 的通道零，与固定权重掩码正交。</li><li>ReLU / ReLU² 把零写进函数；SwiGLU 基座不能推理期改装。</li><li>加速取决于门控核与热 token 的最坏零率。</li><li>无专家通信，条件计算发生在稠密 FFN 内部。</li><li>出处：Mirzadeh et al., ICLR 2024。</li></ul>',5))])}const _=A(p,[["render",L]]);export{F as __pageData,_ as default};
